"""П-42 v2: отчёт `docs/findings/p42-level-breakout-v2-2026-11-14.md` из JSON-результатов (числа не набираются руками).

  P42_ROOT=data/p42v2 python tools/p42/make_doc_v2.py > docs/findings/p42-level-breakout-v2-2026-11-14.md
Читает: report.json (шаг A, 1м), report-tick-tickfull8.json (шаг B, после правки разбора цен), report-tick-tickfull-v7.json (до правки),
report-reentry.json (§13.5), outsiders-summary.json, outsiders-excl.json.
"""
import json
import os

ROOT = os.environ.get("P42_ROOT", "data/p42v2")


def J(name):
    return json.load(open(os.path.join(ROOT, name), encoding="utf-8"))


def n(x, d=2, sign=True):
    s = ("%+." + str(d) + "f") % x if sign else ("%." + str(d) + "f") % x
    return s.replace("-", "−").replace(".", ",")


def ci(h):
    return "%s [%s; %s]" % (n(h["mean"]), n(h["lo"]), n(h["hi"]))


def cell(h):
    return "%s, n=%d (%s/сут.)" % (ci(h), h["trades"], n(h["trades_per_day"], 2, False))


def verdict_ru(v):
    return v


SIDE = {"long": "Лонг", "short": "Шорт"}


def table_cands(res, names, title_map):
    out = ["| кандидат | половина A (15.09–14.10) | половина B (15.10–13.11) | вердикт §10 |", "|---|---|---|---|"]
    for k in names:
        c = res["cand"].get(k)
        if not c:
            continue
        a, b = c["halves"]["A"], c["halves"]["B"]
        out.append("| %s | %s | %s | %s |" % (title_map.get(k, k), cell(a), cell(b), c["verdict"]))
    return "\n".join(out)


def main():
    A = J("report.json")
    T = J("report-tick-tickfull8.json")
    T7 = J("report-tick-tickfull-v7.json")
    R = J("report-reentry.json")
    LT = J("report-lat.json")
    OS = J("outsiders-summary.json")
    EX = J("outsiders-excl.json")
    p = []
    w = p.append

    w("# П-42 версия 2 (универсум ≥ $12 млн, 566 монет; вход и выходы по сделкам Binance): пробой часового уровня, лонг и шорт отдельно — отчёт (14.11.2026)\n")
    w("**Вердикт одной строкой (измерено, 60 суток 15.09–13.11, $500 на сделку, тариф владельца, проскальзывание 1 bp). Основное чтение шага B — задержка 200 мс на входы и выходы (слова владельца «ну давай задержка будет 0.2»; lat 0 физически невыполним: 55–64 % входов в ту же миллисекунду, что сделка-сигнал):**")
    la, lb = T["long"]["cand"]["base"]["halves"]["A"], T["long"]["cand"]["base"]["halves"]["B"]
    sa, sb = T["short"]["cand"]["base"]["halves"]["A"], T["short"]["cand"]["base"]["halves"]["B"]
    lb0 = LT["long"]["база|вход+выход 200"]["halves"]
    sb0 = LT["short"]["база|вход+выход 200"]["halves"]
    w("- **Лонг: на минутках опровергнуто (устойчиво), на сделках при реализуемой задержке — не ясно.** Минутки (шаг A, 566 монет): база %s в A и %s в B $/сут.; без 2 худших суток и монет знак «−» держится. Сделки, задержка 200 мс: база A %s, B %s (интервалы накрывают 0, без 2 худших суток знак «+») — «не ясно», как и все три топ-3 и оба варианта повторного входа; «опровергнуто» остаётся только при lat 0 (нереализуемом). Перекрёстный кандидат — 0 сделок на обоих шагах. Края нет, но и устойчивого минуса на сделках нет." % (
        n(A["long"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["long"]["cand"]["base"]["halves"]["B"]["mean"]), n(lb0["A"]["mean"]), n(lb0["B"]["mean"])))
    w("- **Шорт: опровергнуто на сделках (через половину B), на минутках — не ясно; шаги расходятся.** Минутки: база %s / %s (не ясно), перекрёстный %s / %s (не ясно). Сделки, задержка 200 мс: база A %s, B %s ([%s; %s]; без 2 худших суток %s, без 2 худших монет %s — знак держится, интервал накрывает 0), перекрёстный A %s / B %s (не ясно), топ-3 (семья be=0) — опровергнуты через B. Положительный знак минутной базы на сделках не воспроизводится (раздел «Почему шорт на минутках «+», на сделках «−»»)." % (
        n(A["short"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["base"]["halves"]["B"]["mean"]),
        n(A["short"]["cand"]["crossfit"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["crossfit"]["halves"]["B"]["mean"]),
        n(sb0["A"]["mean"]), n(sb0["B"]["mean"]), n(sb0["B"]["lo"]), n(sb0["B"]["hi"]), n(sb0["B"]["no_worst2_days"]["mean"]), n(sb0["B"]["no_worst2_coins"]["mean"]),
        n(LT["short"]["перекрёстный|вход+выход 200"]["halves"]["A"]["mean"]), n(LT["short"]["перекрёстный|вход+выход 200"]["halves"]["B"]["mean"])))
    w("- **Повторный вход по уровню (§13.5, оба варианта) ничего не меняет:** повторы — 0–3 % сделок; вердикты те же (при 200 мс: лонг — не ясно, шорт база — опровергнуто), ни один кандидат не подтверждён.")
    w("- **Абсолютные аутсайдеры** найдены и перечислены (раздел ниже; CSV `data/p42v2/outsiders-{long,short}.csv`); вне выборки, где они выбраны, их исключение базу не улучшает (|Δ| ≤ $2,6/сут., почти все интервалы накрывают 0); список — не фильтр для бота без новых суток (найдено на этих данных).")
    w("- **3,4 млн «плохих строк» aggTrades (0,6 %) выяснены:** это цены меньше 0,001 в записи `9.16E-4`; после правки разбора — 0 плохих строк, вердикты не изменились.\n")
    w("Числа — **измерено** на Binance USD-M. «Опровергнуто»/«не ясно» — по правилу §10 протокола `docs/research/P-42-level-breakout.md` (дополнен §13), Холм — по накопленному счётчику испытаний (лонг 207, шорт 199). Всё «найдено на этих данных»: ни одной проверки на новых сутках; демо-ожидание «после издержек», не прогноз.\n")

    w("## Протокол и данные")
    w("- Протокол: `docs/research/P-42-level-breakout.md` §13 (записан и закоммичен до счёта: `2356b172`; §13.5 «повторный вход» — `d1b86074` и `d24226a2`, тоже до счёта). Слова владельца 14.11: «надо грузить от 12 млн суточного объема»; «да давай для бинанса агтрейды»; про вариант с повторным входом — «ну сделай».")
    w("- Универсум шага A: **566** бессрочных Binance USD-M с оборотом ≥ $12 млн хотя бы в один день 01.09–13.11 (227 прежних + 339 новых). Окна: прогрев 01.09–14.09, A 15.09–14.10, B 15.10–13.11 (по 30 суток).")
    w("- Шаг B: сделки `aggTrades` (`transact_time` в мс, цена как в файле), 566 монет; вход — следующая агрессивная сделка стороны (± 1 bp), тейки — только строго через цену, стоп — по цене пробившей сделки (§13.2).")
    w("- Код: ветка `bb/42-v2-finish-v1-thr_7cy3ypv2kx` (от `bb/42-rerun-12m-ticks-v1-thr_fefbsq7ncj` @ e0539507); модуль `src/breakout/` (`tick.rs`, 1238 тестов, clippy `-D warnings`, fmt — зелёные на srv). Бинари на srv `/data/p42v2/bin/alpha-p42-v{5…10}`; результаты — `/data/p42v2/out/`, локально `data/p42v2/` (gitignored).\n")

    # ---------------- шаг A
    w("## Шаг A: минутки, 566 монет")
    for side in ("long", "short"):
        r = A[side]
        w("### %s" % SIDE[side])
        w("Испытаний шага A: %d (v1 %d + v2 %d); Холм по накопленному m = %d, z = %s; PBO %s (%d конфигураций)." % (
            r["m_package"], r["prior_trials"], r["trials"], r["m_package"], n(r["z_holm"], 2, False), n(r["pbo"]["pbo"], 2, False), r["pbo"]["configurations"]))
        names = [k for k in ("base", "crossfit", "letter") if k in r["cand"]]
        if side == "short" or r["cand"]["letter"]["halves"]["A"]["mean"] != 0 or True:
            pass
        w(table_cands(r, [k for k in names if not (k == "letter" and r["cand"]["letter"]["verdict"] == r["cand"]["crossfit"]["verdict"] and r["cand"]["letter"]["halves"]["A"]["mean"] == r["cand"]["crossfit"]["halves"]["A"]["mean"])],
                      {"base": "база (правила витрины)", "crossfit": "перекрёстный (значения из другой половины)", "letter": "«по букве» протокола (справочно)"}))
        w("")
        b = r["cand"]["base"]["halves"]
        w("База: после первого дня монеты с оборотом ≥ $12 млн — A %s, B %s $/сут.; прежние 227 монет — A %s, B %s; новые 339 — A %s, B %s." % (
            n(b["A"]["after_first_day"]["mean"]), n(b["B"]["after_first_day"]["mean"]), n(b["A"]["old_coins"]), n(b["B"]["old_coins"]), n(b["A"]["new_coins"]), n(b["B"]["new_coins"])))
        w("Без 2 лучших суток: A %s, B %s; без 2 лучших монет: A %s, B %s.\n" % (
            n(b["A"]["no_best2_days"]["mean"]), n(b["B"]["no_best2_days"]["mean"]), n(b["A"]["no_best2_coins"]["mean"]), n(b["B"]["no_best2_coins"]["mean"])))

    # ---------------- шаг B
    w("## Шаг B: вход и выходы по сделкам")
    tm = {"base": "тик-база (lat 0, 1 bp)", "crossfit": "тик-перекрёстный", "top:v_n_bounce_3": "топ-3: n_bounce=3", "top:v_e_0p1": "топ-3: e=0,1",
          "top:v_tf_240": "топ-3: tf=240", "top:j_be_0__t_low_2": "топ-3: be=0, t_low=2", "top:v_be_0": "топ-3: be=0", "top:j_be_0__t_low_3": "топ-3: be=0, t_low=3"}
    for side in ("long", "short"):
        r = T[side]
        w("### %s" % SIDE[side])
        w("Испытаний шага B: %d (база 1 + перекрёстный 2 + топ-3); накопленный m = %d (шаг A %d), z Холма = %s. Топ-3 — отбор на тех же данных («найдено на этих данных»), справочно." % (
            r["n_step_b"], r["m"], r["m_step_a"], n(r["z_holm"], 2, False)))
        w(table_cands(r, list(r["cand"].keys()), tm))
        w("")
        w("Задержка входа и проскальзывание (справочно, не испытания; $/сут., [95 %], сделок):")
        w("")
        w("| вариант | A | B |")
        w("|---|---|---|")
        for k, v in r["sens"].items():
            if v["statA"]["trades"] == 0 and v["statB"]["trades"] == 0:
                continue
            nm = k.replace("b0_", "база ").replace("cross_", "перекрёстный ").replace("lat", "задержка ").replace("slip", "проскальзывание ")
            w("| %s | %s [%s; %s], n=%d | %s [%s; %s], n=%d |" % (nm, n(v["A"]), n(v["statA"]["lo"]), n(v["statA"]["hi"]), v["statA"]["trades"], n(v["B"]), n(v["statB"]["lo"]), n(v["statB"]["hi"]), v["statB"]["trades"]))
        w("")
    w("**Минутки против сделок (база).** Сделок в 3–4 раза больше (лонг A: 86 → 344, B: 106 → 373; шорт A: 76 → 311, B: 70 → 313), потому что сигнал стоит на первом подходе в зону внутри минутки — в том числе в минутках, которые потом пересекают уровень (1м такие пропускает). Шорт на минутках около нуля (%s / %s), на сделках — минус, особенно в B (%s): доля стопов шорта выросла с %.1f %% / %.1f %% (1м, A/B) до 9 %% / 17 %% (сделки). Пример из разбора предыдущего прогона (TAKEUSDT, не пересчитан): вход по нижней сделке «флеш-вика» (свип 5 %% за 1 мс), стоп через 1 мс, −$25 — артефакт нулевой задержки; при задержке 250/1000 мс шорт-убыток в B сокращается до %s / %s, но знак остаётся отрицательным." % (
        n(A["short"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["base"]["halves"]["B"]["mean"]), n(sb["mean"]),
        A["short"]["cand"]["base"]["halves"]["A"]["stop_share"] * 100, A["short"]["cand"]["base"]["halves"]["B"]["stop_share"] * 100,
        n(T["short"]["sens"]["b0_lat250"]["B"]), n(T["short"]["sens"]["b0_lat1000"]["B"])))
    w("Лонг при задержке 250/1000 мс: A %s / %s, B %s / %s — интервалы накрывают 0, знак «−» во всех клетках; при проскальзывании 0 → 5 bp база лонга %s → %s в A.\n" % (
        n(T["long"]["sens"]["b0_lat250"]["A"]), n(T["long"]["sens"]["b0_lat1000"]["A"]), n(T["long"]["sens"]["b0_lat250"]["B"]), n(T["long"]["sens"]["b0_lat1000"]["B"]),
        n(T["long"]["sens"]["b0_slip0"]["A"]), n(T["long"]["sens"]["b0_slip5"]["A"])))

    # ---------------- основное чтение: задержка
    w("## Основное чтение: задержка 200 мс на входы и выходы (§13.4 п. 6, §13.6)")
    w("- **Почему не lat 0.** При lat 0 вход — следующая агрессивная сделка стороны, часто в ту же миллисекунду, что сделка-сигнал: лонг A 189/344, B 198/373; шорт A 199/311, B 187/313 (55–64 %) — внутри чужой серии рыночных заявок, реагирующий ордер так не исполняется. Шорт B: эти входы несут −$640 из −$778 за половину. Владелец: «ну давай задержка будет 0.2» → основное чтение — `lat = 200` мс на входы **и** выходы; граница — 1000 мс; lat 0 и 250 — справочно. Задержка была предрегистрирована как справочная ось (§13.2 п. 5); величина — параметр модели, названный владельцем, не подбор по результату; испытаний не добавляет.")
    w("- **Задержка выходов.** Документация робота Викинг (`https://fkviking.github.io/bot-doc/docs/algorithm-comments.html`, «О ценах выставления заявок второй ноги» и «Особенности поведения заявок, переставленных по SL или Timer»): стоп-лосс на стороне клиента — при срабатывании робот переставляет заявку на `bid − k_sl` / `offer + k_sl` и переставляет её раз в секунду до сведения в сделку. Модель `latx`: стоп/БУ/трейл срабатывают на сделке `T` по правилу §13.2, исполняются по цене первой сделки ≥ `T + latx` (тейкер, −1 bp), тейки до этого остаются лимитками; `k_sl` и очередь не моделируются. **Оговорка:** задержка позволяет цене вернуться после «вика», поэтому задержка выходов улучшает результат (модель без ценового сдвига `k_sl`) — справочное чтение, не прогноз.\n")
    tags = ["lat 0", "вход+выход 200", "вход 250", "вход+выход 250", "вход 1000", "вход+выход 1000"]
    for side in ("long", "short"):
        w("### %s: вердикты по задержке ($/сут. [95 %%], сделок; «без 2 худших» — среднее без 2 худших суток / 2 худших монет)" % SIDE[side])
        w("")
        w("| кандидат | задержка | A | B | без 2 худших A (сутки / монеты) | без 2 худших B | вердикт §10 |")
        w("|---|---|---|---|---|---|---|")
        for key, v in LT[side].items():
            nm, tg = key.split("|")
            if tg not in tags:
                continue
            if v["halves"]["A"]["trades"] == 0 and v["halves"]["B"]["trades"] == 0:
                continue
            a, b = v["halves"]["A"], v["halves"]["B"]
            w("| %s | %s | %s | %s | %s / %s | %s / %s | %s |" % (nm, tg, cell(a), cell(b), n(a["no_worst2_days"]["mean"]), n(a["no_worst2_coins"]["mean"]),
                                                                n(b["no_worst2_days"]["mean"]), n(b["no_worst2_coins"]["mean"]), v["verdict"]))
        w("")
    w("**Устойчивость опровержения на шаге A (1м, 566 монет), без 2 худших суток / без 2 худших монет:** лонг база A %s / %s, B %s / %s (знак «−» держится — опровержение устойчиво); шорт база A %s / %s, B %s / %s (знак «+», не опровергнуто). Для кандидатов с 0 сделок устойчивость не определена.\n" % (
        n(A["long"]["cand"]["base"]["halves"]["A"]["no_worst2_days"]["mean"]), n(A["long"]["cand"]["base"]["halves"]["A"]["no_worst2_coins"]["mean"]),
        n(A["long"]["cand"]["base"]["halves"]["B"]["no_worst2_days"]["mean"]), n(A["long"]["cand"]["base"]["halves"]["B"]["no_worst2_coins"]["mean"]),
        n(A["short"]["cand"]["base"]["halves"]["A"]["no_worst2_days"]["mean"]), n(A["short"]["cand"]["base"]["halves"]["A"]["no_worst2_coins"]["mean"]),
        n(A["short"]["cand"]["base"]["halves"]["B"]["no_worst2_days"]["mean"]), n(A["short"]["cand"]["base"]["halves"]["B"]["no_worst2_coins"]["mean"])))
    w("### Почему шорт на минутках «+», на сделках «−» (обе причины в цифрах)")
    w("Тик-база разложена на сделки, у которых есть «1м-двойник» (та же монета, уровень и сигнальная минута есть среди сделок 1м-базы; приближённо — портфель 1м и тика отличается), и «дополнительные» (вход до пробоя в минутках, которые 1м пропускает), а также на входы в ту же миллисекунду, что сигнал, и более поздние ($/сут.):\n")
    import csv as _csv
    for side in ("short", "long"):
        m1 = list(_csv.DictReader(open(os.path.join(ROOT, "stage1", "b0", side + "-trades.csv"))))
        k1 = {(t["sym"], t["level"], t["sig_min"]) for t in m1}
        w("**%s.**" % SIDE[side])
        w("")
        w("| задержка входа | группа | сделок A | $/сут. A | сделок B | $/сут. B |")
        w("|---|---|---|---|---|---|")
        for lab, d in (("0 мс", "tick-tickfull8/b0"), ("250 мс", "tick-tickfull8/b0_lat250")):
            T_ = list(_csv.DictReader(open(os.path.join(ROOT, d, side + "-trades.csv"))))
            tab = {}
            for t in T_:
                h = "A" if int(t["entry_day"]) < 30 else "B"
                key = ("1м-двойник" if (t["sym"], t["level"], t["sig_min"]) in k1 else "дополнительный (до пробоя)", "в ту же мс" if t["entry_ms"] == t["sig_ms"] else "позже")
                e = tab.setdefault(key, {"A": [0, 0.0], "B": [0, 0.0]})
                e[h][0] += 1
                e[h][1] += float(t["net"])
            for key in sorted(tab):
                e = tab[key]
